/* Inventário em slots: a arte é separada dos controles e dos dados do personagem. */
(function(){'use strict';const $=id=>document.getElementById(id),C=MythosCore,I=InventoryModel;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const itemIcon=i=>i.slot==='weapon'?14:i.slot==='shield'?15:I.SLOTS.find(s=>s.key===i.slot)?.icon??1;
const weaponGhost='<svg class="weapon-ghost" viewBox="0 0 32 32" aria-hidden="true"><path d="M3 3 7 5 25 23 23 25 5 7z" fill="#71796f"/><path d="m19 23 4-4 2 2-4 4zM23 25l4 4 2-2-4-4z" fill="#696f66"/><path d="M5 5 24 24" stroke="#a0a79a" stroke-width=".6"/></svg>';
const linked='<svg class="hand-link" viewBox="0 0 20 20" aria-hidden="true"><g fill="none" stroke="#e2c98a" stroke-width="2"><rect x="2" y="6" width="9" height="6" rx="3" transform="rotate(-35 7 9)"/><rect x="9" y="7" width="9" height="6" rx="3" transform="rotate(-35 13 10)"/></g></svg>';
const coin='<svg viewBox="0 0 36 30" aria-hidden="true"><g stroke="#936419" stroke-width="1"><ellipse cx="12" cy="21" rx="10" ry="6" fill="#be8b29"/><ellipse cx="12" cy="17" rx="10" ry="6" fill="#e1b854"/><ellipse cx="12" cy="13" rx="10" ry="6" fill="#f0cd76"/><ellipse cx="12" cy="13" rx="7" ry="4" fill="none" stroke="#fff0b3"/><ellipse cx="24" cy="23" rx="10" ry="6" fill="#d5a23e"/><ellipse cx="24" cy="21" rx="10" ry="6" fill="#f0cb6b"/><ellipse cx="24" cy="21" rx="7" ry="4" fill="none" stroke="#fff0ad"/></g></svg>';
// Ícones da aba cosmética: nenhuma estatística é alterada nesta seção.
const cosmeticShapes={
 weapon:'<path d="m5 4 6 3 24 25-3 3L7 11Z"/><path d="m27 35 8-8 4 4-8 8Z"/><path d="m34 38 7 7 4-4-7-7Z"/>',
 head:'<path d="M24 5C14 9 9 20 7 37l10-6 7 13 7-13 10 6C39 20 34 9 24 5Z"/><path d="m13 30 11-9 11 9-11 14Z" class="cosmetic-cutout"/>',
 body:'<path d="m15 7-11 7 6 12 6-3v20h16V23l6 3 6-12-11-7-9 7Z"/><path d="m19 9 5 5 5-5M24 14v9" class="cosmetic-seam"/>',
 hands:'<path d="m5 25 3-10 3 1 3-9 3 1-2 12 5-14 3 1-4 15 6-11 3 2-7 17-2 13H8l-1-10-4-7Z"/><path d="m27 27 2-8 3 1 2-9 3 1-1 12 5-13 3 1-3 15 4-7 2 2-6 14-1 8H27l-1-10-3-6Z"/>',
 legs:'<path d="M12 6h24l-1 15 6 22H28l-4-20-4 20H7l6-22Z"/><path d="M13 11h22" class="cosmetic-seam"/>',
 feet:'<path d="m8 7 12 1-2 23 5 7-1 5H4l-1-6 4-7Z"/><path d="m29 7 12 1-2 23 6 7-1 5H26l-1-6 3-7Z"/><path d="M8 13h11M29 13h11" class="cosmetic-seam"/>'
};
const cosmeticIcon=key=>'<svg class="cosmetic-icon" viewBox="0 0 48 48" aria-hidden="true">'+cosmeticShapes[key]+'</svg>';
class MythosInventory{
 constructor(game){this.g=game;this.tab='Normal';this.dropOpen=false;this.selected=null;this.atlas=new Image();this.reference=new Image();this.atlas.onload=()=>this.paint();this.reference.onload=()=>this.paint();this.atlas.src='__INVENTORY_ITEMS__';this.reference.src='__INVENTORY_REFERENCE__';}
 dismiss(){this.dropOpen=false;this.tab='Normal';this.selected=null;const popup=$('coinPopup');if(popup)popup.hidden=true;const main=$('inventoryMain');if(main)main.inert=false;}
 art(kind){return '<canvas width="96" height="96" data-art="'+kind+'" aria-hidden="true"></canvas>';}
 render(tab=this.tab){
  tab=I.TABS.includes(tab)?tab:'Normal';this.tab=tab;this.dropOpen=false;this.selected=null;const p=this.g.p,clothes=tab==='Roupas',entries=clothes?[]:I.entries(p);
  let equipment='';
  if(tab==='Normal')equipment=I.SLOTS.map(s=>{const item=s.key==='offhand'?C.offhandItem(p):C.ITEMS[p.equipment[s.key]],twoHands=C.twoHanded(item)&&['weapon','offhand'].includes(s.key),name=(item?item.name+' · ':'')+s.name+(twoHands?' · Duas mãos: um único item':'');return '<button class="equip-slot '+(item?'filled rarity-'+item.rarity:'empty')+'" data-slot="'+s.key+'" '+(item?'draggable="true"':'')+' style="left:'+s.x+'%;top:'+s.y+'%" title="'+esc(name)+'" aria-label="'+esc(name+(item?'':': vazio'))+'">'+(!item&&['weapon','offhand'].includes(s.key)?weaponGhost:this.art('gear-'+(item?itemIcon(item):s.icon)))+(twoHands&&s.key==='offhand'?linked:'')+'</button>';}).join('');
  else equipment='<section class="clothes-equipment" aria-label="Conjuntos visuais e skins">'+I.COSMETIC_SLOTS.map(slot=>'<button class="equip-slot cosmetic-slot empty" data-cosmetic-slot="'+slot.key+'" style="left:'+slot.x+'%;top:'+slot.y+'%" title="'+esc(slot.name)+' · vazio" aria-label="'+esc(slot.name)+': vazio" aria-disabled="true">'+cosmeticIcon(slot.icon)+'</button>').join('')+'</section>';
  let grid='';for(let n=0;n<I.CAPACITY;n++){const entry=entries[n],item=entry?.kind==='gear'?C.ITEMS[entry.id]:null;grid+='<button class="bag-slot '+(item?'rarity-'+item.rarity:entry?'has-potion':'bag-empty')+'" data-cell="'+n+'" '+(entry?'draggable="'+(entry.kind==='gear')+'" title="'+esc(item?item.name:entry.id==='hp'?'Poção de vida':'Poção de mana')+'"':'aria-label="Espaço vazio '+(n+1)+'"')+'>'+ (entry?this.art(entry.kind==='gear'?'gear-'+itemIcon(item):entry.id)+(entry.kind==='potion'?'<b class="stack-count">'+entry.count+'</b>':''):'')+'</button>';}
  $('modalTitle').textContent='Inventário';
  $('modalBody').innerHTML='<div id="inventoryRoot" class="'+(clothes?'inventory-clothes':'inventory-normal')+'"><div id="inventoryMain"><h2 class="inventory-title">Inventário</h2><button id="inventoryClose" class="inv-close" title="Fechar inventário [Esc]" aria-label="Fechar inventário">×</button><nav class="inventory-tabs" aria-label="Seções do inventário">'+I.TABS.map(t=>'<button data-inv-tab="'+t+'" class="'+(t===tab?'active':'')+'" aria-pressed="'+(t===tab)+'">'+t+'</button>').join('')+'</nav>'+equipment+'<div class="inv-divider"></div>'+(clothes?'<h3 class="clothes-collection-title">Coleção de visuais</h3>':'')+'<div class="bag-grid" aria-label="'+(clothes?'Coleção de visuais com 48 espaços':'Mochila com 48 espaços')+'">'+grid+'</div><footer class="inventory-footer"><span id="inventoryCapacity">'+entries.length+' / '+I.CAPACITY+'</span><div class="inventory-currency"><button id="coinDropTrigger" title="Soltar moedas" aria-label="Abrir janela Soltar moedas">'+coin+'</button><span id="inventoryGold">'+p.gold.toLocaleString('pt-BR')+'</span></div></footer><section id="inventoryItemDetail" hidden></section></div><section id="coinPopup" role="dialog" aria-modal="true" aria-labelledby="coinPopupTitle" hidden><header><h3 id="coinPopupTitle">Soltar moedas</h3><button id="coinDropClose" aria-label="Fechar janela de moedas">×</button></header><label for="coinDropAmount">Digite o valor:</label><div class="coin-entry"><input id="coinDropAmount" type="text" inputmode="numeric" pattern="[0-9]*" maxlength="16" autocomplete="off" value="0" aria-describedby="coinDropError"><div class="coin-steppers"><button id="coinStepUp" aria-label="Aumentar quantidade">▴</button><button id="coinStepDown" aria-label="Diminuir quantidade">▾</button></div><button id="coinDropMax">Máximo</button></div><p id="coinDropError" role="status"></p><div class="coin-actions"><button id="coinDropOK" disabled>OK</button><button id="coinDropCancel">Cancelar</button></div></section></div>';
  $('inventoryClose').onclick=()=>this.g.close();
  document.querySelectorAll('[data-inv-tab]').forEach(b=>b.onclick=()=>this.render(b.dataset.invTab));
  document.querySelectorAll('[data-cell]').forEach(b=>{const entry=entries[+b.dataset.cell];if(!entry)return;b.onclick=()=>this.showItem(entry);b.ondblclick=()=>this.activate(entry);b.ondragstart=e=>{if(entry.kind==='gear')e.dataTransfer.setData('text/plain',entry.id);};});
  document.querySelectorAll('[data-slot]').forEach(b=>{b.onclick=()=>{const id=b.dataset.slot==='offhand'?C.offhandItem(p)?.id:p.equipment[b.dataset.slot];if(id)this.showItem({id,kind:'gear',equipped:b.dataset.slot});};b.ondragstart=e=>{const id=b.dataset.slot==='offhand'?C.offhandItem(p)?.id:p.equipment[b.dataset.slot];if(id)e.dataTransfer.setData('text/plain',id);};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();this.equip(e.dataTransfer.getData('text/plain'),b.dataset.slot);};});
  $('coinDropTrigger').onclick=()=>this.openDrop();$('coinDropClose').onclick=() =>this.closeDrop();$('coinDropCancel').onclick=()=>this.closeDrop();$('coinDropMax').onclick=()=>{ $('coinDropAmount').value=String(this.g.p.gold);this.validateAmount();};
  $('coinStepUp').onclick=()=>this.step(1);$('coinStepDown').onclick=()=>this.step(-1);$('coinDropAmount').oninput=()=>this.validateAmount();$('coinDropOK').onclick=()=>this.confirmDrop();
  $('coinPopup').onkeydown=e=>{e.stopPropagation();if(e.code==='Escape'){e.preventDefault();this.closeDrop();}else if(e.code==='Enter'&&e.target===$('coinDropAmount')){e.preventDefault();if(!e.repeat)this.confirmDrop();}};
  this.paint();
 }
 paint(){
  if(this.g.panel!=='inventory')return;document.querySelectorAll('[data-art]').forEach(canvas=>{const art=canvas.dataset.art,ctx=canvas.getContext('2d');ctx.clearRect(0,0,96,96);if(art.startsWith('gear-')){if(!this.atlas.complete||!this.atlas.naturalWidth)return;const index=+art.slice(5),cell=this.atlas.naturalWidth/4;ctx.drawImage(this.atlas,index%4*cell,Math.floor(index/4)*cell,cell,cell,5,5,86,86);}else if(this.reference.complete&&this.reference.naturalWidth){const rect=art==='hp'?[151,874,60,58]:[247,874,58,60];ctx.drawImage(this.reference,...rect,8,8,80,80);}});

 }
 showItem(entry){
  this.selected=entry;const detail=$('inventoryItemDetail'),p=this.g.p,item=C.ITEMS[entry.id],worn=item&&C.equippedSlots(p,item.id).length>0;
  detail.hidden=false;detail.innerHTML='<button id="itemDetailClose" aria-label="Fechar detalhes">×</button><h3>'+esc(item?item.name:entry.id==='hp'?'Poção de vida':'Poção de mana')+'</h3><p>'+esc(item?item.description:entry.id==='hp'?'Recupera 80 de vida.':'Recupera 60 de mana em 5 segundos.')+'</p>'+(item?'<p class="item-requirements">Nível '+item.minLevel+' · '+Object.entries(item.req).map(([k,v])=>({forca:'Força',destreza:'Destreza',magia:'Magia',vitalidade:'Vitalidade'}[k])+' '+v).join(' · ')+'<br>'+ (item.slot==='weapon'?(C.twoHanded(item)?'Duas mãos · ocupa os dois espaços<br>':'Uma mão<br>'):'')+ (item.power?'Poder '+item.power.toFixed(1):'Defesa física '+item.def.toFixed(1))+'</p>':'')+'<button id="itemDetailAction">'+(worn?'Retirar':item?'Equipar':'Usar')+'</button>';
  $('itemDetailClose').onclick=()=>detail.hidden=true;$('itemDetailAction').onclick=()=>worn?this.unequip(entry.equipped||C.equippedSlots(p,item.id)[0]):this.activate(entry);
 }
 activate(entry){if(entry.kind==='gear')this.equip(entry.id);else{this.g.close();this.g.potion(entry.id);}}
 equip(id,targetSlot=null){const item=C.ITEMS[id];if(!item||targetSlot&&!C.slotCompatible(item,targetSlot)){this.g.toast('Este item não é compatível com o slot.');return false;}if(!C.equip(this.g.p,id,targetSlot)){this.g.toast('Verifique os requisitos do item e o espaço da mochila.');return false;}this.g.action=null;this.g.lastBasicHand=null;if(!C.shieldItem(this.g.p))this.g.blockTime=0;this.g.sound.tone(410,.15,'triangle',.02,1.3);this.g.save();this.render();return true;}
 unequip(slot){if(!C.unequip(this.g.p,slot)){this.g.toast('Não foi possível retirar: confira o espaço na mochila.');return false;}this.g.action=null;this.g.lastBasicHand=null;if(!C.shieldItem(this.g.p))this.g.blockTime=0;const s=C.stats(this.g.p);this.g.p.hp=Math.min(s.hp,this.g.p.hp);this.g.p.mp=Math.min(s.mp,this.g.p.mp);this.g.save();this.render();return true;}
 openDrop(){if(this.g.panel!=='inventory')return;this.dropOpen=true;$('inventoryItemDetail').hidden=true;$('inventoryMain').inert=true;$('coinPopup').hidden=false;$('coinDropAmount').value='0';$('coinDropError').textContent=this.g.p.gold<1?'Você não possui moedas para soltar.':'';this.validateAmount();$('coinDropAmount').focus();$('coinDropAmount').select?.();}
 closeDrop(){this.dropOpen=false;const popup=$('coinPopup');if(popup)popup.hidden=true;const main=$('inventoryMain');if(main)main.inert=false;$('coinDropTrigger')?.focus();}
 validateAmount(){const amount=I.dropAmount($('coinDropAmount').value,this.g.p.gold);$('coinDropOK').disabled=amount===null;$('coinDropMax').disabled=this.g.p.gold<1;return amount;}
 step(delta){const field=$('coinDropAmount'),n=Number(field.value);field.value=String(Math.max(0,Math.min(this.g.p.gold,(Number.isSafeInteger(n)?n:0)+delta)));this.validateAmount();}
 confirmDrop(){if(!this.dropOpen)return false;const amount=this.validateAmount();if(amount===null){$('coinDropError').textContent='Informe um número inteiro entre 1 e '+this.g.p.gold.toLocaleString('pt-BR')+'.';return false;}if(!this.g.dropGold(amount)){ $('coinDropError').textContent='Não foi possível soltar as moedas aqui.';return false;}this.closeDrop();this.render();return true;}
}
window.MythosInventory=MythosInventory;
})();
